    else if (count == 4) bin = (w3d_u8)(bin >> 2);
    else if (count == 2) bin = (w3d_u8)(bin >> 3);
    else bin = 0;

    if (bin >= count) bin = (w3d_u8)(count - 1);
    return model->edge_masks[(__safe_index w3d_u8)bin];
}

